# Хорошо: у всех объектов одна форма
class User
  def initialize(name, email)
    @name = name
    @email = email
    @admin = false        # даже если пока не нужно
  end
end

# Плохо: форма зависит от данных
class Draft
  def initialize(attrs)
    @title = attrs[:title] if attrs[:title]
    @body  = attrs[:body]  if attrs[:body]  # 4 возможные формы
  end

  def publish!
    @published_at = Time.now   # ещё одна ветка дерева форм
  end
end
